22	/**
23	 * Capsule T6 — platform-admin revert of a PUBLISHED event back to DRAFT.
24	 *
25	 * ATDD: every test here is intentionally RED until the revert action exists.
26	 */
27	#[Group('events')]
28	class AdminRevertToDraftTest extends FeatureTestCase
29	{
30	    use BillingTestFixtures;
31	
32	    #[Test]
33	    public function platform_admin_reverts_a_published_event_without_registrations_to_draft(): void
34	    {
35	        [$organiser] = $this->adminWithPlan(PlanTier::GROWTH);
36	        $superAdmin = $this->platformSuperAdminFor($organiser->currentTeam);
37	        $event = $this->eventFor($organiser, EventState::PUBLISHED);
38	
39	        $this->actingAs($superAdmin)
40	            ->post(route('admin.events.revert-to-draft', $event->uuid), ['reason' => 'Published by mistake'])
41	            ->assertRedirect();
42	
43	        $this->assertSame(EventState::DRAFT, $this->persisted($event)->state);
44	
45	        // AC2 — the move must land through the guarded transition path, which is
46	        // observable as its audit record for the published -> draft edge.
47	        $transition = Activity::query()
48	            ->where('log_name', EventAuditEvents::EVENT_TRANSITIONED)
49	            ->where('subject_id', $event->id)
50	            ->latest('id')
51	            ->first();
52	
53	        $this->assertNotNull($transition, 'Expected a guarded transition audit record for the revert.');
54	        $this->assertSame($superAdmin->id, (int) $transition->causer_id);
55	        $this->assertSame(EventState::PUBLISHED->value, data_get($transition->properties, 'from'));
56	        $this->assertSame(EventState::DRAFT->value, data_get($transition->properties, 'to'));
57	    }
58	
59	    #[Test]
60	    public function workspace_admin_without_the_platform_capability_is_refused(): void
61	    {
62	        [$organiser] = $this->adminWithPlan(PlanTier::GROWTH);
63	        $event = $this->eventFor($organiser, EventState::PUBLISHED);
64	
65	        $this->actingAs($organiser)
66	            ->post(route('admin.events.revert-to-draft', $event->uuid), ['reason' => 'Let me undo this'])
67	            ->assertForbidden();
68	
69	        $this->assertNotReverted($event, EventState::PUBLISHED);
70	    }
71	
72	    #[Test]
73	    public function revert_is_refused_when_the_event_is_not_published(): void
74	    {
75	        [$organiser] = $this->adminWithPlan(PlanTier::GROWTH);
76	        $superAdmin = $this->platformSuperAdminFor($organiser->currentTeam);
77	        $event = $this->eventFor($organiser, EventState::PREPARING);
78	
79	        $this->actingAs($superAdmin)
80	            ->post(route('admin.events.revert-to-draft', $event->uuid), ['reason' => 'Support request']);
81	
82	        $this->assertNotReverted($event, EventState::PREPARING);
83	    }
84	
85	    #[Test]
86	    public function revert_is_refused_when_the_event_already_has_registrations(): void
87	    {
88	        [$organiser] = $this->adminWithPlan(PlanTier::GROWTH);
89	        $superAdmin = $this->platformSuperAdminFor($organiser->currentTeam);
90	        $event = $this->eventFor($organiser, EventState::PUBLISHED);
91	        $this->registerAttendee($event);
92	
93	        $this->actingAs($superAdmin)
94	            ->post(route('admin.events.revert-to-draft', $event->uuid), ['reason' => 'Support request']);
95	
96	        $this->assertNotReverted($event, EventState::PUBLISHED);
97	    }
98	
99	    #[Test]
100	    public function cancelled_event_cannot_be_reverted(): void
101	    {
102	        [$organiser] = $this->adminWithPlan(PlanTier::GROWTH);
103	        $superAdmin = $this->platformSuperAdminFor($organiser->currentTeam);
104	        $event = $this->eventFor($organiser, EventState::PUBLISHED);
105	        $event->forceFill([
106	            'cancelled_at' => now(),
107	            'cancelled_by' => $organiser->id,
108	            'cancel_reason' => 'Speaker emergency',
109	        ])->save();
110	
111	        $this->actingAs($superAdmin)
112	            ->post(route('admin.events.revert-to-draft', $event->uuid), ['reason' => 'Support request']);
113	
114	        $fresh = $this->persisted($event);
115	        $this->assertSame(EventState::PUBLISHED, $fresh->state);
116	        $this->assertNotNull($fresh->cancelled_at);
117	        $this->assertNotReverted($event, EventState::PUBLISHED);
118	    }
119	
120	    #[Test]
121	    public function only_the_published_to_draft_edge_is_added_to_the_canonical_table(): void
122	    {
123	        $expectedEdges = [
124	            EventState::DRAFT->value => ['published', 'suspended', 'failed'],
125	            EventState::PUBLISHED->value => ['preparing', 'suspended', 'failed', 'draft'],
126	            EventState::PREPARING->value => ['ready', 'failed', 'suspended'],
127	            EventState::READY->value => ['live', 'failed', 'suspended'],
128	            EventState::LIVE->value => ['ended', 'failed', 'suspended', 'ready'],
129	            EventState::ENDED->value => ['failed', 'suspended'],
130	            EventState::FAILED->value => ['preparing', 'suspended'],
131	            EventState::SUSPENDED->value => [],
132	        ];
133	
134	        foreach (EventState::cases() as $state) {
135	            $actual = array_map(static fn (EventState $s) => $s->value, $state->transitionsTo());
136	            sort($actual);
137	            $expected = $expectedEdges[$state->value];
138	            sort($expected);
139	
140	            $this->assertSame($expected, $actual, "Legal edges changed for {$state->value}.");
141	        }
142	
143	        // State-derived rules other code reads from the table keep their answers.
144	        foreach (EventState::cases() as $state) {
145	            $this->assertSame(
146	                $state !== EventState::DRAFT,
147	                $state->isMetadataLocked(),
148	                "Metadata lock changed for {$state->value}.",
149	            );
150	            $this->assertSame(
151	                in_array($state, [EventState::DRAFT, EventState::ENDED, EventState::FAILED, EventState::SUSPENDED], true),
152	                $state->blocksRegistration(),
153	                "Registration blocking changed for {$state->value}.",
154	            );
155	            $this->assertSame(
156	                ! in_array($state, [EventState::DRAFT, EventState::FAILED, EventState::SUSPENDED], true),
157	                $state->isPubliclyIndexable(cancelled: false),
158	                "Public indexability changed for {$state->value}.",
159	            );
160	            $this->assertSame(
161	                $state !== EventState::SUSPENDED,
162	                $state->canBeSuspendedFrom(),
163	                "Suspend reachability changed for {$state->value}.",
164	            );
165	        }
166	    }
167	
168	    private function assertNotReverted(Event $event, EventState $expected): void
169	    {
170	        $this->assertSame($expected, $this->persisted($event)->state);
171	
172	        $this->assertFalse(
173	            Activity::query()
174	                ->where('log_name', EventAuditEvents::EVENT_TRANSITIONED)
175	                ->where('subject_id', $event->id)
176	                ->where('properties->to', EventState::DRAFT->value)
177	                ->exists(),
178	            'A refused revert must not record a transition to draft.',
179	        );
180	    }
181	
182	    private function persisted(Event $event): Event
183	    {
184	        return Event::query()
185	            ->withoutGlobalScope(TeamScope::class)
186	            ->findOrFail($event->id);
187	    }
188	
189	    private function eventFor(User $organiser, EventState $state): Event
190	    {
191	        return Event::factory()
192	            ->inState($state)
193	            ->for($organiser->currentTeam)
194	            ->create(['created_by' => $organiser->id]);
195	    }
196	
197	    private function registerAttendee(Event $event): void
198	    {
199	        $email = 'registrant-'.$event->id.'@example.test';
200	
201	        (new Registration)->forceFill([
202	            'team_id' => $event->team_id,
203	            'event_id' => $event->id,
204	            'email' => $email,
205	            'email_hash' => hash('sha256', $email),
206	            'full_name' => 'Early Registrant',
207	            'consent_accepted_at' => now(),
208	            'consent_ip' => '203.0.113.10',
209	        ])->save();
210	    }
211	
212	    private function platformSuperAdminFor(Team $workspace): User
213	    {
214	        /** @var User $user */
215	        $user = User::factory()->create([
216	            'email_verified_at' => now(),
217	            'current_team_id' => $workspace->id,
218	        ]);
219	
220	        $workspace->users()->attach($user, ['role' => UserRole::SYSTEM_ADMIN->value]);
221	
222	        /** @var User $fresh */
223	        $fresh = $user->fresh(['currentTeam']);
224	
225	        return $fresh;
226	    }
227	}
