29	class EventStateMachineService
30	{
31	    public function __construct(
32	        private readonly AuditLoggerInterface $auditLogger,
33	        private readonly EventRepositoryInterface $events,
34	        private readonly EventAuthorizationService $authz,
35	    ) {}
