275	        $this->authz->authorizeForceEnd($event, $actor);
276	
277	        // 2. LIVE-only pre-check — throw before delegating to transition() so
278	        //    non-LIVE sources get IllegalStateTransition immediately. Cancelled
279	        //    LIVE events bypass this (state is still LIVE) and reach transition()'s
280	        //    native cancelled_at re-check which throws EventStateLocked.
281	        if ($event->state !== EventState::LIVE) {
282	            throw IllegalStateTransition::between($event->state, EventState::ENDED);
