/**
 * T6 — platform-admin revert of a PUBLISHED event back to DRAFT.
 * Capability is enforced by route.permission (events.publish.global) and
 * re-asserted in EventModerationService::revertToDraft.
 */
public function revertToDraft(Request $request, Event $event): JsonResponse|RedirectResponse
{
    $request->validate(['reason' => ['required', 'string', 'max:500']]);

    try {
        $result = $this->eventService->revertToDraft(
            event: $event,
            actor: authUser(),
            reason: $request->string('reason')->toString(),
        );
    } catch (EventDomainException $e) {
        return $this->domainErrorResponse($request, $e, 'moderation');
    }

    if (! $request->expectsJson()) {
        return redirect()
            ->back()
            ->with('status', __('events.show.moderation.messages.reverted_to_draft'));
    }

    return response()->json([
        'data' => ['uuid' => $result->uuid, 'state' => $result->state->value],
    ]);
}

